const errors = $input.all().filter(item => item.json.error);

const posts = $input.all()
  .filter(item => !item.json.error)
  .map(item => item.json);

return [
  {
    json: {
      source: 'mastodon.social',
      status: errors.length > 0 ? 'error' : 'success',
      posts,
      post_count: posts.length,
      errors: errors.map(item => ({
        message: item.json.error?.message,
        status: item.json.error?.status,
        description: item.json.details?.description
      }))
    }
  }
];

const errors = $input.all().filter(item => item.json.error);

const posts = $input.all()
  .filter(item => !item.json.error)
  .map(item => item.json);

return [
  {
    json: {
      source: 'social.espeweb.net',
      status: errors.length > 0 ? 'error' : 'success',
      posts,
      post_count: posts.length,
      errors: errors.map(item => ({
        message: item.json.error?.message,
        status: item.json.error?.status,
        description: item.json.details?.description
      }))
    }
  }
];

const sources = $input.all().map(item => item.json);

const posts = sources.flatMap(source => source.posts || []);

const successfulSources = sources.filter(
  source => source.status === 'success'
);

const failedSources = sources.filter(
  source => source.status === 'error'
);

return [
  {
    json: {
      status:
        successfulSources.length === 2 ? 'success' :
        successfulSources.length === 1 ? 'partial_success' :
        'error',
      total_posts: posts.length,
      successful_sources: successfulSources.map(source => source.source),
      failed_sources: failedSources.map(source => ({
        source: source.source,
        errors: source.errors
      })),
      posts
    }
  }
];

